/*
 * Purpose: round a double down by clearing its fractional IEEE-754 bits.
 *
 * Hypothesis: this is the fdlibm floor implementation in the nearby libm
 * range.  The word-level form preserves signed zero, raises inexact through
 * a large addition, and returns NaNs by adding the argument to itself.
 *
 * PARKED: the now-available fixed group-A check is nonexact.  The unchanged
 * public Newlib 1.12.0 fdlibm unit is also nonexact (624 generated bytes
 * against the 620-byte target), so provenance is not a library classification.
 */
typedef union {
    double value;
    struct {
        unsigned int low;
        int high;
    } words;
} DoubleWords;

double FUN_08807aa8(double value)
{
    DoubleWords bits;
    unsigned int mask;
    unsigned int incremented_low;
    int exponent;
    static const double huge = 1.0e300;

    bits.value = value;
    exponent = ((bits.words.high >> 20) & 0x7ff) - 0x3ff;

    if (exponent < 20) {
        if (exponent < 0) {
            if (huge + value > 0.0) {
                if (bits.words.high >= 0) {
                    bits.words.high = 0;
                    bits.words.low = 0;
                } else if (((bits.words.high & 0x7fffffff) | bits.words.low) != 0) {
                    bits.words.high = 0xbff00000;
                    bits.words.low = 0;
                }
            }
        } else {
            mask = 0x000fffffU >> exponent;
            if (((bits.words.high & (int)mask) | bits.words.low) == 0) {
                return value;
            }
            if (huge + value > 0.0) {
                if (bits.words.high < 0) {
                    bits.words.high += 0x00100000 >> exponent;
                }
                bits.words.high &= ~(int)mask;
                bits.words.low = 0;
            }
        }
    } else if (exponent > 51) {
        if (exponent == 0x400) {
            return value + value;
        }
        return value;
    } else {
        mask = 0xffffffffU >> (exponent - 20);
        if ((bits.words.low & mask) == 0) {
            return value;
        }
        if (huge + value > 0.0) {
            if (bits.words.high < 0) {
                if (exponent == 20) {
                    bits.words.high += 1;
                } else {
                    incremented_low = bits.words.low + (1U << (52 - exponent));
                    if (incremented_low < bits.words.low) {
                        bits.words.high += 1;
                    }
                    bits.words.low = incremented_low;
                }
            }
            bits.words.low &= ~mask;
        }
    }

    return bits.value;
}
